/** Copilot chat: the operation catalogue and the message shapes an app renders.
 *
 * There is no bespoke chat API on the platform. EVERY chat operation is one
 * `executeWorkflowNode` call against the callables app, carrying the automation id
 * for that operation:
 *
 *   context: { appName: 'callables', resourceName: 'callables_call_automation' }
 *   inputs:  { automationId, synchronous: true, parameters: { … } }
 *
 * The ids themselves are configuration — see `useCopilotConfig`. This file only
 * names the operations and the response shapes.
 */
/** Operation -> the key its automation id is stored under in the copilot config.
 * Mirrors `AIActions` in @unifyapps/defs; kept as a plain const so the SDK stays
 * standalone (the app it is bundled into does not have @unifyapps/defs). */
declare const CopilotAction: {
    /** send a message; creates the case (conversation) on the first one */
    readonly CreateCase: "create_case_automation";
    /** a page of history, newest-first, for one case */
    readonly FetchConversation: "fetch_conversation_automation";
    /** one message by id — what a push notification resolves to */
    readonly FetchMessageById: "fetch_message_by_id_automation";
    /** everything after a given message; the catch-up read after a dropped stream */
    readonly FetchMessagesAfterMessageId: "fetch_conversation_after_previous_fan_message";
    /** re-attach to a response still being generated */
    readonly ResumeSSE: "resume_streaming_automation";
    /** interrupt the in-flight response */
    readonly StopResponseGeneration: "stop_response_generation_automation";
    /** empty the conversation */
    readonly ClearMessageList: "clear_conversation_automation";
    /** the user's conversations, for a chat switcher */
    readonly FetchCaseList: "fetch_case_list_automation";
    /** re-run the last response */
    readonly RetryCase: "retry_response_automation";
    readonly FetchMessageAttachment: "fetch_attachment_by_message_id_automation";
    readonly MarkAsRead: "mark_as_read_automation";
    readonly PinUnpinMessage: "pin_unpin_message_automation";
    readonly Feedback: "feedbackAutomation";
};
type CopilotActionKey = (typeof CopilotAction)[keyof typeof CopilotAction];
/** The copilot config record's `properties`: operation key -> automation id, plus
 * the config's own `type`. Not every deployment defines every operation, so every
 * lookup is optional.
 *
 * `type` is echoed back to EVERY automation as `copilotType` — the automations
 * branch on it, so a call without it is answered for the wrong copilot. */
type CopilotAutomationConfig = Partial<Record<CopilotActionKey, string>> & {
    type?: string;
};
/** Which copilot the config is for. An app built with this SDK talks to an AI
 * agent, so `AI_AGENT` is the only one that applies — the rest exist on the
 * platform (live chat, model comparison, node debugging …) and are listed so the
 * value is recognisable rather than a bare string. */
declare const CopilotConfigType: {
    readonly AIAgent: "AI_AGENT";
    readonly LiveChat: "LIVE_CHAT";
};
type CopilotConfigTypeValue = (typeof CopilotConfigType)[keyof typeof CopilotConfigType];
/** The wire values, straight from defs' `MessageType` (Chat/types.ts). The user's own
 * message is **'Fan'**, not 'USER' — guessing the obvious spelling here means every
 * message renders as the agent's and the optimistic copy is never retired. */
declare const MessageType: {
    readonly User: "Fan";
    readonly Bot: "Bot";
    readonly Brand: "Brand";
};
/** What KIND of thing a bot message is. Carried at `additional.internalMessageType`.
 *
 * This is not cosmetic. A THOUGHT is the agent narrating its own work ("Searching
 * the web") and the platform renders it as a PILL with no body text — it is
 * deliberately excluded from the message text. Rendering thoughts as chat bubbles
 * turns one answer into a wall of half-sentences. */
declare const InternalMessageType: {
    readonly Response: "RESPONSE";
    readonly Thought: "THOUGHT";
    readonly Citation: "CITATION";
};
/** What the agent is doing right now, for the loader above the composer.
 *
 *   IDLE                 nothing in flight
 *   THINKING             sent, nothing back yet — a static "Thinking…"
 *   GENERATING_THOUGHTS  a thought pill is live — show its label, shimmering
 *   GENERATING_RESPONSE  the answer is streaming in — no loader, the text IS the signal
 *   AWAITING_USER        the agent asked a clarifying question, or is waiting on an
 *                        interactive interface (a tool approval) — NO loader; it is
 *                        blocked on the user, and a spinner over the reply buttons
 *                        reads as "still working"
 */
declare const CopilotAgentState: {
    readonly Idle: "IDLE";
    readonly Thinking: "THINKING";
    readonly GeneratingThoughts: "GENERATING_THOUGHTS";
    readonly GeneratingResponse: "GENERATING_RESPONSE";
    readonly AwaitingUser: "AWAITING_USER";
};
type CopilotAgentStateValue = (typeof CopilotAgentState)[keyof typeof CopilotAgentState];
/** One rendered message. The platform returns a good deal more per message
 * (citations, reactions, assignment, tool calls); this is the subset an app needs
 * to draw a conversation, and unknown fields survive on the object. */
interface CopilotMessage {
    messageId: string;
    caseId?: string;
    messageType?: string;
    /** the rendered blocks — `[{ blockType: 'Typography', data: { type, text } }]`. This
     * is the field the wire uses (NOT `content`), and the one streaming deltas target
     * with paths like `message[0].data.text`. */
    message?: unknown;
    /** kept for callers that hand us a pre-adapted message; `message` is the wire field */
    content?: unknown;
    /** plain text of the message, concatenated from its Typography blocks */
    text?: string;
    /** how `text` is authored — 'MARKDOWN' for an AI agent, so render it as markdown
     * rather than printing it raw. Lifted off the first Typography block. */
    contentType?: string;
    createdTime?: number;
    /** present while this message is still streaming — render a caret/spinner */
    isStreaming?: boolean;
    /** RESPONSE / THOUGHT / CITATION — see InternalMessageType. Read off
     * `additional.internalMessageType` and lifted here for convenience. */
    internalType?: string;
    /** true for a THOUGHT: render it as a pill, never as a message bubble */
    isThought?: boolean;
    additional?: {
        internalMessageType?: string;
        /** present when the agent asked a clarifying question — the turn is open but
         * it is waiting on the user (drives AWAITING_USER) */
        clarifications?: unknown[];
        [key: string]: unknown;
    };
    /** set when the message carries something for the canvas (a PDF, a sheet, a
     * chart, a figma frame). The canvas is not a separate channel: it is this
     * field on an ordinary message. */
    previewDetails?: CopilotPreviewDetails;
    /** set when the message embeds a published interface page instead of prose */
    interfaceDetails?: {
        interfaceId?: string;
        /** the interface stays interactive mid-turn — the agent is parked on it waiting
         * for the user to act (a tool approval, a form it asked for). Drives AWAITING_USER. */
        whitelistInteractions?: boolean;
        [key: string]: unknown;
    };
    [key: string]: unknown;
}
interface CopilotPreviewDetails {
    /** what to show — the platform's own preview descriptor, passed through */
    type?: string;
    url?: string;
    thumbnail?: {
        display?: string;
        url?: string;
    };
    [key: string]: unknown;
}
interface CopilotConversationPage {
    messages?: CopilotMessage[];
    additional?: {
        /** 'pending' while a response is being generated; the poll ladder keys off it */
        responseGenerationStatus?: string;
        generatingResponse?: boolean;
        [key: string]: unknown;
    };
    [key: string]: unknown;
}
/** One row in the history rail. The case-list automation returns these; `summary` is the
 * generated title the platform shows, falling back to the id when it has none yet. */
interface CopilotConversation {
    caseId: string;
    summary?: string;
    createdTime?: number;
    [key: string]: unknown;
}

interface UseCopilotChatOptions {
    /** which agent answers. Passed through to the automations; the automation ids
     * themselves are shared across agents (see useCopilotConfig). */
    aiAgentId?: string;
    /** resume an existing conversation; omit to start a new one */
    chatId?: string;
    configType?: CopilotConfigTypeValue;
    /** how many messages a history page holds */
    pageSize?: number;
    /** stream the answer token by token (default). Set false to fall back to the
     * poll ladder alone — the answer then lands in one piece a few seconds later. */
    stream?: boolean;
}
/** A whole copilot conversation: history, sending, live updates and canvas.
 *
 * Everything below is one shape — `messages` is the conversation, `send` adds to
 * it, `isGenerating` says whether the agent is still answering, and `canvas` is
 * whatever the latest message asked to display. An app renders those four and
 * nothing else; the transport underneath is not its problem.
 *
 * ## How updates arrive
 *
 * The platform offers three channels and this uses two of them:
 *
 *   * **polling** — a re-read of the conversation, fast (5s) while a response is
 *     generating and slow (15s) once it is not. This is the one that always works.
 *   * **catch-up reads** — after sending, and whenever generation ends, so the
 *     final message lands even if a stream was cut.
 *   * MQTT is deliberately NOT used. The platform's own client subscribes to a
 *     per-case topic for instant delivery, but that needs a broker connection and
 *     credentials an embedded app does not have. Polling covers the same ground
 *     with a bounded delay, and no setup.
 *
 * A true token-by-token stream needs `callables_call_automation_sse` and an SSE
 * reader; `sendStreaming` is where that goes, and is left out of this first cut on
 * purpose — see the note on it below.
 */
declare function useCopilotChat(options?: UseCopilotChatOptions): {
    /** the conversation to render as bubbles — thoughts excluded */
    messages: CopilotMessage[];
    /** the agent narrating its work; render as pills, not bubbles */
    thoughts: CopilotMessage[];
    /** IDLE / THINKING / GENERATING_THOUGHTS / GENERATING_RESPONSE / AWAITING_USER */
    agentState: CopilotAgentStateValue;
    /** label of the thought currently running, when there is one */
    currentThought: string | undefined;
    /** every message including thoughts, in order, if you want to interleave them */
    allMessages: CopilotMessage[];
    chatId: string | undefined;
    canvas: CopilotPreviewDetails | undefined;
    /** past conversations for a history rail; call `loadChats()` to populate */
    chats: CopilotConversation[];
    loadChats: (searchQuery?: string) => Promise<void>;
    openChat: (nextChatId: string) => void;
    newChat: () => void;
    send: (text: string, extra?: Record<string, unknown>) => Promise<void>;
    stop: () => Promise<void>;
    clear: () => Promise<void>;
    loadOlder: () => Promise<void>;
    hasMore: boolean;
    isGenerating: boolean;
    isSending: boolean;
    isLoading: boolean;
    /** false when the tenant has no copilot config — nothing can be called */
    isConfigured: boolean;
    error: {} | null;
};

/** The automation id for every chat operation, for one kind of copilot.
 *
 * This is the piece that makes the rest of the SDK's chat surface work: nothing
 * can be called until you know WHICH automation implements it, and that mapping is
 * configuration on the platform, not something an app can hardcode.
 *
 * It is keyed by config TYPE, not by agent — one `AI_AGENT` config serves every
 * agent in the tenant, and the agent is chosen per conversation via `aiAgentId`.
 * So this resolves once and never changes: `staleTime: Infinity`, and the same
 * query is shared by every copilot on the page.
 */
declare function useCopilotConfig(configType?: CopilotConfigTypeValue): {
    config: CopilotAutomationConfig | undefined;
    isLoading: boolean;
    error: ErrorType<unknown> | null;
    /** A tenant with no copilot config cannot chat at all, and the failure is
     * otherwise silent — every operation would just have no automation to call.
     * Surface it so the app can say so instead of rendering a dead input. */
    isConfigured: boolean;
};

export { CopilotAction, CopilotAgentState, CopilotConfigType, InternalMessageType, MessageType, useCopilotChat, useCopilotConfig };
export type { CopilotActionKey, CopilotAgentStateValue, CopilotAutomationConfig, CopilotConfigTypeValue, CopilotConversationPage, CopilotMessage, CopilotPreviewDetails, UseCopilotChatOptions };
